/* 保养任务规则，无DOM；所有状态和权限由接口执行。 */
(function(root){const node=typeof module==='object'&&module.exports,need=(node?require('./maintenance-rules.js'):root.EamMaintenanceRules).need;
const participant=(t,c)=>t.primaryPersonId===c.person||t.collaboratorIds.includes(c.person);
function actions(t,c,config){const closure=node?require('./maintenance-closure-rules.js'):root.EamMaintenanceClosureRules;config||=node?require('./maintenance-data.js').config:root.EAM_MAINTENANCE_JSON.config;if(t.termination?.status==='pending_review')return {...Object.fromEntries(['assign','start','save','discoveries','submit','pause','resume','cancel'].map(k=>[k,false])),...closure.actions(t,c,config)};const supervisor=c.role==='supervisor',primary=t.primaryPersonId===c.person,working=t.status==='in_progress';return {assign:supervisor&&['pending_assignment','ready','in_progress','paused'].includes(t.status),start:primary&&t.status==='ready',save:participant(t,c)&&working,discoveries:participant(t,c)&&working,submit:primary&&working,pause:primary&&working,resume:(primary||supervisor)&&t.status==='paused',cancel:supervisor&&['pending_assignment','ready'].includes(t.status),...closure.actions(t,c,config), 'request-early-start':(primary||supervisor)&&['ready','paused'].includes(t.status)&&config.asOfDate<t.windowStart&&t.earlyStart?.status!=='pending'&&!earlyValid(t,config), 'apply-early-start-result':config.terminationRoles.includes(c.role)&&['ready','paused'].includes(t.status)&&t.earlyStart?.status==='pending'};}
function people(snapshot,c){return [...new Set(snapshot.bindings.flatMap(b=>b.type==='person'?[b.id]:(c.positions.find(p=>p.id===b.id)?.members||[])))].filter(id=>c.people.some(p=>p.id===id));}
function earlyValid(t,c){const a=t.earlyStart;return !!a&&a.status==='approved'&&a.requestedStartAt<=c.asOfDate&&a.effectiveUntil>=c.asOfDate&&a.executionVersion===t.executionVersion&&a.primaryPersonId===t.primaryPersonId&&JSON.stringify(a.collaboratorIds)===JSON.stringify(t.collaboratorIds)&&a.windowStart===t.windowStart&&a.windowEnd===t.windowEnd;}
function check(t,c){const date=c.asOfDate,qualified=id=>c.qualifications.some(q=>q.personId===id&&q.validFrom<=date&&q.validTo>=date&&q.status==='valid');const checks=[{label:'执行窗口或有效提前开工授权',passed:!!t.windowStart&&!!t.windowEnd&&(date>=t.windowStart||earlyValid(t,c))},{label:'设备在用',passed:c.equipment.some(e=>e.id===t.equipmentId&&e.status==='active')},{label:'主责当前资格有效',passed:!!t.primaryPersonId&&qualified(t.primaryPersonId)},{label:'协作人员当前资格有效',passed:t.collaboratorIds.every(qualified)},{label:'计划人员范围仍有效',passed:t.snapshot.assignmentValidFrom<=date&&(!t.snapshot.assignmentValidTo||t.snapshot.assignmentValidTo>=date)}];const permit=c.permits.find(p=>p.equipmentId===t.equipmentId&&p.status==='approved'&&p.validFrom<=date&&p.validTo>=date&&p.scope==='maintenance');checks.push({label:'专业许可与隔离控制有效',passed:!!permit});return {allowed:checks.every(x=>x.passed),checks,permit:permit||null,checkedOn:date,overdue:date>t.windowEnd,earlyStartInstanceId:date<t.windowStart&&earlyValid(t,c)?t.earlyStart.instanceId:null};}
function results(t,body,actor,complete=false){need(Array.isArray(body.results),'项目结果必须为数组');need(new Set(body.results.map(x=>x.itemId)).size===body.results.length,'项目结果重复');for(const r of body.results){const item=t.snapshot.items.find(i=>i.id===r.itemId);need(item,'项目不属于任务快照');need(['','normal','abnormal'].includes(r.conclusion||''),'项目结论无效');if(r.value!==undefined&&r.value!=='')need(Number.isFinite(Number(r.value)),'数值结果无效');if(item.resultType==='number'&&r.value!==undefined&&r.value!==''&&(Number(r.value)<Number(item.min)||Number(r.value)>Number(item.max)))need(r.conclusion==='abnormal','数值越限须记录异常');}if(complete){for(const i of t.snapshot.items){const r=body.results.find(r=>r.itemId===i.id);if(!i.required&&(!r||(!r.conclusion&&(r.value===undefined||r.value==='')&&!r.evidence?.trim()&&!r.followup?.trim())))continue;need(r&&['normal','abnormal'].includes(r.conclusion),'项目结果不完整');if(i.resultType==='number')need(r.value!==''&&r.value!==undefined&&Number.isFinite(Number(r.value)),'数值项目结果必填');if(i.evidenceRequired)need(r.evidence?.trim(),'项目证据必填');if(r.conclusion==='abnormal')need(r.followup?.trim()&&t.anomalyLinks.some(l=>l.itemId===i.id&&l.status==='linked'&&l.discoveryId),'异常项目须已关联发现和后续处置说明');}need(Number.isFinite(Number(body.laborMinutes))&&Number(body.laborMinutes)>0,'工时须大于0');need(body.trial?.trim(),'试运行结论必填');}return body.results.map(r=>({...r,actorId:actor,recordedAt:new Date().toISOString()}));}
const api={need,actions,participant,people,check,earlyValid,results};if(node)module.exports=api;else root.EamMaintenanceTaskRules=api;})(typeof window!=='undefined'?window:globalThis);
